/**
 * BACKEND-GAPS.md renderer.
 *
 * Every output repo gets one. It names everything the rebuild could NOT
 * recover (RLS policies, edge functions, triggers, storage buckets, auth
 * config, payment flows, secrets) with concrete manual migration steps.
 * Honest partial recovery: listed, never silently invented.
 */
import type { UnvibeSpec } from './spec.js';

export function renderBackendGaps(spec: UnvibeSpec): string {
  const lines: string[] = [
    '# BACKEND-GAPS.md',
    '',
    '> Generated by Unvibe. This file lists everything the automated rebuild',
    '> could **not** recover from the captured app. Each item needs manual',
    '> migration. Nothing here was invented — if it is not listed, it was',
    '> either recovered (see the repo) or not observed at all.',
    '',
    `Source: ${spec.source.url}`,
    `Spec version: ${spec.specVersion} (unvibe ${spec.source.unvibeVersion}, captured ${spec.source.capturedAt})`,
    `Auth provider detected: ${spec.auth.provider}`,
    '',
    '---',
    '',
  ];
  if (spec.gaps.length === 0) {
    lines.push('No unrecoverable gaps recorded. (No backend integrations were observed in capture.)', '');
  }
  spec.gaps.forEach((g, i) => {
    lines.push(`## ${i + 1}. ${g.title}`, '');
    lines.push(`**Category:** \`${g.category}\` · **Recoverable automatically:** no`, '');
    lines.push(g.description, '');
    lines.push('**Manual migration steps:**', '');
    g.manualSteps.forEach((s, j) => lines.push(`${j + 1}. ${s}`));
    lines.push('');
  });
  lines.push(
    '---',
    '',
    '## What WAS recovered',
    '',
    `- ${spec.routes.length} route(s): ${spec.routes.map((r) => `\`${r.path}\``).join(', ')}`,
    `- ${spec.endpoints.length} API endpoint(s) observed (client call-sites regenerated)`,
    `- ${spec.entities.length} data entit${spec.entities.length === 1 ? 'y' : 'ies'} inferred from observed payloads → \`drizzle/schema.ts\` + \`supabase/migrations/\``,
    `- ${spec.assets.length} static asset(s) copied into \`public/assets/\``,
    '',
    '## Fidelity promise',
    '',
    'Unvibe guarantees **route-level and contract-level fidelity**: the same',
    'routes exist, the same API endpoints are called with the same shapes,',
    'and the same data model is created. Pixel-perfect UI is explicitly out',
    'of scope — verify with `unvibe verify` and judge the screenshots yourself.',
    '',
  );
  return lines.join('\n');
}
